files.content:
:root {
  --bg: #0f172a;
  --card: #1e293b;
  --accent: #38bdf8;
  --accent-strong: #0ea5e9;
  --text: #e2e8f0;
  --muted: #94a3b8;
  --pixel: #38bdf8;
  --pixel-off: #1e293b;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: radial-gradient(circle at 50% 0%, #1e293b 0%, #0f172a 70%);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  border-radius: 20px;
  padding: 28px 24px 32px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
  text-align: center;
}

h1 {
  margin: 0 0 20px;
  font-size: 1.4rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.clock-section {
  margin-bottom: 24px;
}

.pixel-display {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  flex-wrap: wrap;
  font-family: 'Courier New', monospace;
  font-size: clamp(2rem, 12vw, 3.4rem);
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--pixel);
  text-shadow: 0 0 12px rgba(56, 189, 248, 0.5);
  padding: 12px 0;
}

.digit-group {
  display: inline-block;
  min-width: 2ch;
}

.colon {
  color: var(--muted);
  animation: blink 1s steps(1) infinite;
}

@keyframes blink {
  50% { opacity: 0.25; }
}

.ampm {
  font-size: 0.45em;
  margin-left: 8px;
  color: var(--accent);
  align-self: flex-end;
  padding-bottom: 6px;
}

.controls {
  margin-bottom: 28px;
}

button {
  font: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 22px;
  border-radius: 12px;
  border: 2px solid var(--accent);
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

button:hover {
  background: rgba(56, 189, 248, 0.12);
  box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.15);
}

button:focus-visible {
  outline: 3px solid var(--accent-strong);
  outline-offset: 3px;
}

button:active {
  background: var(--accent-strong);
  color: #0f172a;
  transform: scale(0.97);
}

.stopwatch-section h2 {
  margin: 0 0 8px;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.stopwatch {
  font-family: 'Courier New', monospace;
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text);
  letter-spacing: 0.06em;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 20px 16px 24px;
  }
  .pixel-display {
    gap: 2px;
  }
}

(function () {
  'use strict';

  var hoursEl = document.getElementById('hours');
  var minutesEl = document.getElementById('minutes');
  var secondsEl = document.getElementById('seconds');
  var ampmEl = document.getElementById('ampm');
  var toggleBtn = document.getElementById('toggle-format');
  var stopwatchEl = document.getElementById('stopwatch');
  var announceEl = document.getElementById('clock-announce');

  var use24Hour = false;
  var startTime = Date.now();
  var lastAnnouncedMinute = -1;

  function pad(n) {
    return n < 10 ? '0' + n : String(n);
  }

  function formatElapsed(ms) {
    var totalSeconds = Math.floor(ms / 1000);
    var h = Math.floor(totalSeconds / 3600);
    var m = Math.floor((totalSeconds % 3600) / 60);
    var s = totalSeconds % 60;
    return pad(h) + ':' + pad(m) + ':' + pad(s);
  }

  function renderClock() {
    var now = new Date();
    var h = now.getHours();
    var m = now.getMinutes();
    var s = now.getSeconds();
    var suffix = '';

    if (!use24Hour) {
      suffix = h >= 12 ? 'PM' : 'AM';
      h = h % 12;
      if (h === 0) h = 12;
    }

    hoursEl.textContent = pad(h);
    minutesEl.textContent = pad(m);
    secondsEl.textContent = pad(s);

    if (use24Hour) {
      ampmEl.hidden = true;
    } else {
      ampmEl.hidden = false;
      ampmEl.textContent = suffix;
    }

    if (m !== lastAnnouncedMinute) {
      lastAnnouncedMinute = m;
      announceEl.textContent = 'Current time: ' + hoursEl.textContent + ':' +
        minutesEl.textContent + (use24Hour ? '' : ' ' + suffix);
    }
  }

  function renderStopwatch() {
    stopwatchEl.textContent = formatElapsed(Date.now() - startTime);
  }

  function tick() {
    renderClock();
    renderStopwatch();
  }

  function updateToggleLabel() {
    if (use24Hour) {
      toggleBtn.textContent = 'Switch to 12-hour';
      toggleBtn.setAttribute('aria-pressed', 'true');
    } else {
      toggleBtn.textContent = 'Switch to 24-hour';
      toggleBtn.setAttribute('aria-pressed', 'false');
    }
  }

  toggleBtn.addEventListener('click', function () {
    use24Hour = !use24Hour;
    updateToggleLabel();
    lastAnnouncedMinute = -1;
    renderClock();
  });

  updateToggleLabel();
  tick();
  setInterval(tick, 1000);
})();
